-- Each actual finance copy has its own exact native class and source period.
-- Amounts, identity, original producer hashes and immutable history survive.
-- No default legal duration, invoice deletion, provider traffic or cascade.
BEGIN;
GRANT CREATE ON SCHEMA public TO gridex_ediel_retention_owner;
CREATE TABLE gridex_ediel_retention.finance_class_catalog(retention_class text PRIMARY KEY,source_schema text NOT NULL,source_table text NOT NULL,id_column text NOT NULL,body_columns text[] NOT NULL,permission_key text NOT NULL,source_kind text NOT NULL,operation text NOT NULL,UNIQUE(source_schema,source_table));
