 ('invoice_line_body','public','customer_invoice_lines','id',ARRAY['description','metadata'],'ediel.retention.invoice_copy_evidence','invoice_line','redact_finance_copy_body'),
 ('invoice_export_item_body','public','invoice_export_items','id',ARRAY['request_payload','response_payload','error_payload','status_payload','metadata'],'ediel.retention.invoice_copy_evidence','item','redact_finance_copy_body'),
 ('invoice_export_run_body','public','invoice_export_runs','id',ARRAY['readiness_snapshot','metadata'],'ediel.retention.invoice_copy_evidence','run','redact_finance_copy_body'),
 ('invoice_provider_event_body','public','invoice_provider_events','id',ARRAY['payload'],'ediel.retention.invoice_copy_evidence','provider_event','redact_finance_copy_body'),
 ('invoice_purchase_event_body','public','invoice_purchase_events','id',ARRAY['payload'],'ediel.retention.invoice_copy_evidence','item_child','redact_finance_copy_body'),
 ('invoice_document_provider_body','public','invoice_documents','id',ARRAY['provider_payload'],'ediel.retention.invoice_copy_evidence','item_child','redact_finance_copy_body'),
 ('invoice_dead_letter_body','public','invoice_dead_letters','id',ARRAY['payload','error_message'],'ediel.retention.invoice_copy_evidence','item_child','redact_finance_copy_body'),
 ('invoice_export_attempt_body','public','invoice_export_attempts','id',ARRAY['response_excerpt'],'ediel.retention.invoice_copy_evidence','item_child','redact_finance_copy_body'),
 ('billing_export_item_body','public','billing_export_run_items','id',ARRAY['payload','invoice_address_snapshot','site_address_snapshot','payload_snapshot','adapter_payload_snapshot'],'ediel.retention.invoice_copy_evidence','underlay_child','redact_finance_copy_body'),
 ('partner_export_body','public','partner_exports','id',ARRAY['payload','response_payload','partner_response_log'],'ediel.retention.invoice_copy_evidence','underlay_child','redact_finance_copy_body'),
